32: 	stdlib_complex64_t v;
33: 	stdlib_complex64_t y;
34: 	float re;
35: 	float im;
36: 	int i;
37: 	for ( i = 0; i < 4; i++ ) {
38: 		v = x[ i ];
39: 		stdlib_complex64_reim( v, &re, &im );
40: 		printf( "z = %f + %fi\n", re, im );
41: 
42: 		y = stdlib_base_complex64_mul( v, v );
